  const[clDeptF,   setClDeptF]  = useState("All");

  const openAddCl=(projId=null,dept="Operations",type="Task")=>{setClForm({projectId:projId,type,customType:"",title:"",dept:dept,assignedTo:"",status:"To Do",priority:"Normal",dueDate:"",supplier:"",notes:"",whatCouldGoWrong:"",qty:"",unit:"pcs"});setEditCl(null);setClModal(true);};
  const openEditCl=item=>{setClForm({...item,customType:CL_TYPES.includes(item.type)?"":item.type,whatCouldGoWrong:item.whatCouldGoWrong||"",qty:item.qty||"",unit:item.unit||"pcs"});setEditCl(item.id);setClModal(true);};
  const saveCl=()=>{
    if(!clForm.title||!clForm.title.trim()){toastEmit("Task title is required.","error");return;}
    if(!clForm.dept){toastEmit("Department is required.","error");return;}
    if(clForm.type==="Custom"&&!clForm.customType?.trim()){toastEmit("Please describe the custom task type.","error");return;}
    const finalType=clForm.type==="Custom"&&clForm.customType?clForm.customType.trim():clForm.type;
    if(!finalType){toastEmit("Task type is required.","error");return;}
    const rec={...clForm,type:finalType,id:editCl||uid(),createdDate:today,createdBy:role};
    upChecklist(cs=>editCl?cs.map(c=>c.id===editCl?rec:c):[...cs,rec]);
    if(isSupabaseReady()) sbSyncOne("checklists",rec,toSbChecklist);
    setClModal(false);setEditCl(null);
  };
  const delCl=delChecklist;
  const clStatusQ=(id,st)=>{
    upChecklist(cs=>cs.map(c=>c.id===id?{...c,status:st}:c));
    if(isSupabaseReady()) sbUpdate('checklists',id,{status:st}).catch(e=>{toastEmit("Task status sync failed — check connection.","warning");console.error("clStatusQ:",e);});
    if(st==="Done") toastEmit("Task marked done!","success");
  };

  const pickRole=r=>{setRole(r);localStorage.setItem(KEYS.role,r);};


  // ── Auth helpers ───────────────────────────────────────────────────────────
  const login=async(username,password)=>{
    const unameLower=username.toLowerCase().trim();
    // Always check DEFAULT_USERS first as guaranteed fallback (works before Supabase loads)
    const defUser=DEFAULT_USERS.find(x=>x.username===unameLower);
    let u=users.find(x=>x.username.toLowerCase()===unameLower);
    // If not in local state yet (Supabase still loading), query Supabase directly
    if(!u&&isSupabaseReady()){
      try{
        const{data}=await supabase.from('user_profiles').select('*').ilike('username',unameLower).single();
        if(data) u={id:data.id,username:data.username||"",name:data.name||data.full_name||"",role:data.role||"Sales",title:data.title||data.role||"",status:data.status||"active",passwordHash:data.password_hash||""};
      }catch(e){}
    }
    // If Supabase hasn't loaded yet or user not in DB, fall back to DEFAULT_USERS
    if(!u&&defUser) u={...defUser,status:"active"};
    if(!u) return "Username not found.";
    if(u.status==="pending") return "Your account is pending approval by a Manager.";
    if(u.status==="inactive") return "Your account has been deactivated. Contact Paulo.";
    // Try password; if DB hash is missing, fall back to DEFAULT_USERS hash
    const hashToCheck=u.passwordHash||(defUser?.passwordHash||"");
    let valid=hashToCheck?await checkPw(password,hashToCheck,u.username):false;
    // Secondary check using DEFAULT_USERS hash (handles empty password_hash in Supabase)
    if(!valid&&defUser) valid=await checkPw(password,defUser.passwordHash,u.username);
    if(!valid) return "Incorrect password.";
    // Auto-upgrade legacy btoa hash to SHA-256 on successful login
    if(!hashToCheck.startsWith("sha256:")){
      const newHash=await sha256Hash(password,u.username);
      const upgraded={...u,passwordHash:newHash};
      upUsers(us=>us.map(x=>x.id===u.id?upgraded:x));
      if(isSupabaseReady()) sbUpsert('user_profiles',toSbUser(upgraded),'id').catch(()=>{});
    }
    const sess={userId:u.id,username:u.username,name:u.name,role:u.role,title:u.title||u.role};
    setSession(sess); setRole(u.role);
    logActivity(null,"Login",u.role,sess.name);
    const defaultPages={Manager:"home",Sales:"pipeline",Finance:"home",Procurement:"home",QS:"home",Operations:"home",Design:"home",ProjectMover:"home"};
    setPage(defaultPages[u.role]||"home");
    localStorage.setItem(KEYS.session,JSON.stringify(sess));
    localStorage.setItem(KEYS.role,u.role);
    loadAllFromSupabase();
    return null;
  };
  const logout=async()=>{
    if(supabase){ try{ await Promise.race([supabase.auth.signOut(),new Promise(r=>setTimeout(r,2000))]); }catch(e){} }
    setSession(null);
    setRole(null);
    setAuthView("login");
    setPage("home");
    sessionStorage.removeItem("gmd:lastPage");
    localStorage.removeItem(KEYS.session);
    localStorage.removeItem(KEYS.role);
  };
  const register=async(name,username,password,requestedRole)=>{
    if(!name||!username||!password) return "All fields are required.";
    if(users.find(u=>u.username.toLowerCase()===username.toLowerCase())) return "Username already taken.";
    if(password.length<6) return "Password must be at least 6 characters.";
    const uname=username.toLowerCase();
    const newUser={id:"u"+Date.now(),name,username:uname,passwordHash:await sha256Hash(password,uname),role:requestedRole,status:"pending",createdAt:today};
    upUsers(us=>[...us,newUser]);
    return null;
  };
  const approveUser =(id,role)=>upUsers(us=>us.map(u=>{if(u.id!==id)return u;const n={...u,status:"active",role};if(isSupabaseReady())sbUpsert('user_profiles',toSbUser(n),'id').catch(()=>{});return n;}));
  const rejectUser  =(id)    =>upUsers(us=>us.map(u=>{if(u.id!==id)return u;const n={...u,status:"rejected"};if(isSupabaseReady())sbUpsert('user_profiles',toSbUser(n),'id').catch(()=>{});return n;}));
  const deactivateUser=(id)  =>upUsers(us=>us.map(u=>{if(u.id!==id)return u;const n={...u,status:"inactive"};if(isSupabaseReady())sbUpsert('user_profiles',toSbUser(n),'id').catch(()=>{});return n;}));
  const deleteUser  =(id)    =>{upUsers(us=>us.filter(u=>u.id!==id));if(isSupabaseReady())sbDelete('user_profiles',id).catch(()=>{});};
  const resetPw     =async(id,pw)=>{const u=users.find(x=>x.id===id);if(!u)return;const n={...u,passwordHash:await sha256Hash(pw,u.username)};upUsers(us=>us.map(x=>x.id===id?n:x));if(isSupabaseReady())sbUpsert('user_profiles',toSbUser(n),'id').catch(()=>{});};
  const createUser  =async(name,username,password,role,title)=>{
    const uname=username.toLowerCase().trim();
    const newUser={id:uid(),name:name.trim(),username:uname,passwordHash:await sha256Hash(password,uname),role,title:title.trim()||role,status:"active",createdAt:today};
    upUsers(us=>[...us,newUser]);
    if(isSupabaseReady()) sbUpsert('user_profiles',toSbUser(newUser),'id').catch(()=>{});
  };
  const changePw    =async(oldPw,newPw)=>{
    const u=users.find(x=>x.id===session?.userId);
    if(!u||!(await checkPw(oldPw,u.passwordHash,u.username))) return "Current password is incorrect.";
    if(newPw.length<6) return "New password must be at least 6 characters.";
    const n={...u,passwordHash:await sha256Hash(newPw,u.username)};
    upUsers(us=>us.map(x=>x.id===u.id?n:x));
    if(isSupabaseReady()) sbUpsert('user_profiles',toSbUser(n),'id').catch(()=>{});
    return null;
  };

  // ── Derived ───────────────────────────────────────────────────────────────
  const wonDeals    =useMemo(()=>deals.filter(d=>WON_STAGES.includes(d.stage)),[deals]);
  const completedDeals=useMemo(()=>deals.filter(d=>d.stage==="14 · Completed"),[deals]);
  const closedDeals=useMemo(()=>deals.filter(d=>d.stage==="12 · Close-Out"),[deals]);
  // Auto-create project entries for any won deal that doesn't have one yet
  // Depends on both wonDeals.length AND projs key count so it re-runs after Supabase loads projs
  const projsKeyCount=Object.keys(projs).length;
  useEffect(()=>{
    const missing=wonDeals.filter(d=>!projs[d.id]);
    if(missing.length>0){
      const patch={};
      missing.forEach(d=>{patch[d.id]=emptyProject();});
      upProjs(ps=>({...ps,...patch}));
    }
  // eslint-disable-next-line
  },[wonDeals.length,projsKeyCount]);

  // Auto-mark Finance DONE when project is fully paid
  useEffect(()=>{
    wonDeals.forEach(d=>{
      const ms=billings.filter(b=>b.dealId===d.id&&b.status!=="Cancelled");
      if(ms.length===0) return;
      const allPaid=ms.every(m=>m.status==="Fully Paid");
      const card=pcards[d.id];
      if(allPaid&&card&&!card.departments?.Finance?.done){
        markDeptDone(d.id,"Finance",true);
      }
    });
  // eslint-disable-next-line
  },[billings.length]);
  const projList  =useMemo(()=>wonDeals.filter(d=>projs[d.id]),[wonDeals,projs]);
  const isPauloGate = stage => PAULO_GATE.includes(stage);
  const clientName=useCallback(id=>deals.find(d=>d.id===id)?.client||`Project #${id}`,[deals]);
  const overallProg=p=>{const si=PROD_STAGES.indexOf(p.currentStage);return Math.round(si*25+(p.progress[p.currentStage]||0)*0.25);};
  const costOf    =p=>(p.materials||[]).reduce((s,m)=>s+m.cost,0)+(p.laborCost||0)+(p.overhead||0);
  const marginOf  =(p,d)=>d&&costOf(p)<d.value?Math.round((d.value-costOf(p))/d.value*100):0;
  const totRev    =useMemo(()=>wonDeals.reduce((s,d)=>s+d.value,0),[wonDeals]);
  const totExp    =useMemo(()=>exps.reduce((s,e)=>s+e.amount,0),[exps]);
  const escalations = useMemo(()=>{
    const list = [];
    const todayD = today;
    const in7days = new Date(); in7days.setDate(in7days.getDate()+7);
    const in7str = in7days.toISOString().slice(0,10);
    // O(1) Map lookups instead of O(n) find() on every iteration
    const wonMap  = new Map(wonDeals.map(d=>[d.id,d]));
    const dealMap = new Map(deals.map(d=>[d.id,d]));
    const billedDealIds = new Set(billings.filter(b=>b.status!=='Cancelled').map(b=>b.dealId));
    // E-1: billing milestones overdue
    billings.forEach(b=>{
      if(b.dueDate && b.dueDate < todayD && b.status !== 'Fully Paid' && b.status !== 'Cancelled'){
        const deal = wonMap.get(b.dealId);
        if(deal) list.push({type:'E-1',dealId:b.dealId,client:deal.client,label:`Overdue: ${b.name||b.label||'Invoice'} (due ${b.dueDate})`,severity:'high'});
      }
    });
    // E-2: addenda in Discovered status
    addenda.forEach(a=>{
      if(a.status==='Discovered'){
        const deal = wonMap.get(a.dealId);
        if(deal) list.push({type:'E-2',dealId:a.dealId,client:deal.client,label:`Unresolved scope change: ${a.title||'Addendum'}`,severity:'medium'});
      }
    });
    // E-3: punchlist SLA breach
    wonDeals.forEach(d=>{
      if(d.stage==='11 · Punchlist'){
        const proj = projs[d.id];
        const startDate = proj?.stageDates?.Punchlist?.s;
        if(startDate && bizDaysElapsed(startDate) > BUSINESS_DAYS_SLA){
          list.push({type:'E-3',dealId:d.id,client:d.client,label:`Punchlist SLA breached (${bizDaysElapsed(startDate)} biz days)`,severity:'high'});
        }
      }
    });
    // E-4: DRF deadline within 7 days
    drfs.forEach(drf=>{
      if(drf.designDeadline && drf.status!=='Done' && drf.status!=='Cancelled' && drf.designDeadline>=todayD && drf.designDeadline<=in7str){
        const deal = wonMap.get(drf.dealId)||dealMap.get(drf.dealId);
        const daysLeft = Math.ceil((new Date(drf.designDeadline)-new Date(todayD))/(1000*60*60*24));
        list.push({type:'E-4',dealId:drf.dealId,client:deal?.client||drf.client||'?',label:`DRF ${drf.drfNo||''} deadline in ${daysLeft}d (${drf.designDeadline})`,severity:'medium'});
      }
    });
    // E-5: PO delivery overdue
    prs.forEach(pr=>{
      if(pr.deliveryDate && pr.deliveryDate < todayD && !['Delivered','Cancelled'].includes(pr.status)){
        const deal = wonMap.get(pr.dealId||pr.projectId);
        list.push({type:'E-5',dealId:pr.dealId||pr.projectId,client:deal?.client||'?',label:`PO overdue: ${pr.item||'Item'} (due ${pr.deliveryDate})`,severity:'high'});
      }
    });
    // E-6: Budget requests pending >3 days
    breqs.forEach(br=>{
      if(br.status==='Pending' && br.createdAt){
        const created = new Date(br.createdAt); const diff = Math.floor((new Date()-created)/(1000*60*60*24));
        if(diff>3){
          const deal = wonMap.get(br.dealId);
          list.push({type:'E-6',dealId:br.dealId,client:deal?.client||br.title||'?',label:`Budget request pending ${diff}d: ${br.title||'Request'}`,severity:'low'});
        }
      }
    });
    // E-7: Won projects with no billing milestones — only flag from Fabrication stage onwards
    // Kickoff & Briefing are too early to require milestones
    const BILLING_REQUIRED_STAGES=["08 · Fabrication","09 · Site & Billing","10 · Installation","11 · Punchlist","12 · Close-Out"];
    wonDeals.forEach(d=>{
      if(!billedDealIds.has(d.id)&&BILLING_REQUIRED_STAGES.includes(d.stage)) list.push({type:'E-7',dealId:d.id,client:d.client,label:`No billing milestone set for active project`,severity:'medium'});
    });
    return list;
  },[billings,addenda,wonDeals,projs,drfs,prs,breqs,deals,today]);
  const totColl   =useMemo(()=>wonDeals.reduce((s,d)=>s+d.amountPaid,0),[wonDeals]);
  const totOut    =useMemo(()=>Math.max(0,wonDeals.reduce((s,d)=>s+Number(d.invoiced||0)-Number(d.amountPaid||0),0)),[wonDeals]);

  // Auto-mark overdue billing milestones — runs once when billings load, then daily
  useEffect(()=>{
    if(!billings.length) return;
    const toMark=billings.filter(b=>b.dueDate&&b.dueDate<today&&!['Fully Paid','Cancelled','Overdue'].includes(b.status));
    if(!toMark.length) return;
    upBillings(bs=>bs.map(b=>toMark.find(m=>m.id===b.id)?{...b,status:'Overdue'}:b));
    if(isSupabaseReady()){
      toMark.forEach(b=>sbUpdate('billing_milestones',b.id,{status:'Overdue',updated_at:new Date().toISOString()}).catch(()=>{}));
    }
  },[billings.length,today]); // eslint-disable-line

  // Daily bot alerts: overdue payables + low inventory
  useEffect(()=>{
    if(!isSupabaseReady()||!botSettings?.token) return;
    const overdueP=payables.filter(p=>p.status==="Unpaid"&&p.dueDate&&p.dueDate<today);
    if(overdueP.length>0){
      const total=overdueP.reduce((s,p)=>s+Number(p.amount||0),0);
      const lines=overdueP.slice(0,5).map(p=>`• ${p.payee||p.description||"?"} — ₱${Number(p.amount||0).toLocaleString("en-PH",{maximumFractionDigits:0})} (due ${p.dueDate})`).join("\n");
      const msg=`⚠️ <b>Overdue Payables Alert</b>\n${overdueP.length} payable${overdueP.length!==1?"s":""} overdue — ₱${total.toLocaleString("en-PH",{maximumFractionDigits:0})} total\n\n${lines}${overdueP.length>5?`\n…and ${overdueP.length-5} more`:""}`;
      sendTelegramNotification("financialcontrol",msg);
      sendTelegramNotification("management",msg);
    }
    const lowStock=inventory.filter(i=>i.status!=="Inactive"&&i.reorderPoint>0&&i.qtyOnHand<=i.reorderPoint);
    if(lowStock.length>0){
      const lines=lowStock.slice(0,5).map(i=>`• ${i.name} — ${i.qtyOnHand} ${i.unit} (reorder at ${i.reorderPoint})`).join("\n");
      const msg=`📦 <b>Low Inventory Alert</b>\n${lowStock.length} item${lowStock.length!==1?"s":""} at or below reorder point\n\n${lines}${lowStock.length>5?`\n…and ${lowStock.length-5} more`:""}`;
      sendTelegramNotification("warehouse",msg);
      sendTelegramNotification("procurement",msg);
    }
  },[today]); // eslint-disable-line

  // ── Dashboard KPI memos — pre-computed so render is instant ──────────────
  const pipeDeals      =useMemo(()=>deals.filter(d=>d.stage!=="Cancelled"&&d.stage!=="Did Not Win"&&!WON_STAGES.includes(d.stage)),[deals]);
  const pipeVal        =useMemo(()=>pipeDeals.reduce((s,d)=>s+Number(d.value||0),0),[pipeDeals]);
  const awardReqCnt    =useMemo(()=>deals.filter(d=>d.notes&&d.notes.includes("[AWARD REQUEST")).length,[deals]);
  const overdueInvCnt  =useMemo(()=>billings.filter(b=>b.dueDate&&b.dueDate<today&&b.status!=="Fully Paid"&&b.status!=="Cancelled").length,[billings]);
  const overdueTATCnt  =useMemo(()=>wonDeals.filter(d=>d.stage!=="12 · Close-Out"&&d.stage!=="14 · Completed"&&pcards[d.id]?.targetEndDate&&pcards[d.id].targetEndDate<today&&!DEPT_ORDER.every(dept=>pcards[d.id]?.departments?.[dept]?.done)).length,[wonDeals,pcards]);
  const qsPendingCnt   =useMemo(()=>jos.filter(j=>j.budgetStatus==="QS Budget Pending"&&!Object.values(budgets[j.dealId]||{}).some(v=>Number(v)>0)).length,[jos,budgets]);
  const mrPendingCnt   =useMemo(()=>mreqs.filter(m=>m.status==="Submitted").length,[mreqs]);
  const addendaAlertCnt=useMemo(()=>addenda.filter(a=>!a.salesNotified&&a.status!=="Rejected").length,[addenda]);
  const activeJOCnt    =useMemo(()=>jos.filter(j=>j.status==="Active").length,[jos]);
  const pendingPRCnt   =useMemo(()=>prs.filter(p=>p.status==="Pending Approval").length,[prs]);
  const billOutstanding=useMemo(()=>Math.max(0,billings.reduce((s,m)=>s+Number(m.amount||0)-(m.payments||[]).reduce((ps,p)=>ps+Number(p.amount||0),0),0)),[billings]);
  const overdueInvMs   =useMemo(()=>billings.filter(m=>m.dueDate&&m.dueDate<today&&m.status!=="Fully Paid"&&m.status!=="Cancelled").length,[billings]);
  const breqPendingCnt =useMemo(()=>breqs.filter(b=>b.status==="Pending").length,[breqs]);
  const openPOCnt      =useMemo(()=>prs.filter(p=>["Pending Approval","Approved","PO Issued"].includes(p.status)).length,[prs]);
  const toBuyCnt       =useMemo(()=>swatches.filter(s=>s.status==="To Buy").length,[swatches]);
  const overdueProjectCnt=useMemo(()=>wonDeals.filter(d=>pcards[d.id]?.targetEndDate&&pcards[d.id].targetEndDate<today&&!DEPT_ORDER.every(dept=>pcards[d.id]?.departments?.[dept]?.done)).length,[wonDeals,pcards]);

  // ── Modals ────────────────────────────────────────────────────────────────
  const[dealModal,  setDealModal] =useState(false);
  const[awardModal, setAwardModal]=useState(null);
  const[awardReqModal, setAwardReqModal]=useState(null);
  const[payTermsModal,setPayTermsModal]=useState(null); // dealId — shown after award to capture payment terms
  const[clientSugg, setClientSugg]=useState([]); // autocomplete suggestions
  const[dealForm,  setDealForm] =useState(emptyDeal);
  const[editDeal,  setEditDeal] =useState(null);
  const[expModal,  setExpModal] =useState(false);
  const[routeModal,setRouteModal]=useState(null);
  const[routeMethod,setRouteMethod]=useState("BizLink");
  const[routeBank,setRouteBank]=useState("");
  const[expForm,   setExpForm]  =useState({expDate:today,month:new Date().getMonth(),year:new Date().getFullYear(),category:"Materials",amount:"",note:"",payee:"",projectId:null,bankAccount:"",receipt:""});
  const[editExpId, setEditExpId]=useState(null);
  const[infModal,  setInfModal] =useState(false);
  const[infForm,   setInfForm]  =useState({month:new Date().getMonth(),source:"",amount:"",note:"",projectId:null});
  const[selProj,   setSelProj]  =useState(null);
